from pwn import *
import sys
from binascii import hexlify, unhexlify

def get_cipher(input_data=b''):
    try:
        conn = remote('crypto.chal.csaw.io', 4512, timeout=5)
        conn.recvuntil(b'> ')
        conn.sendline(hexlify(input_data))
        response = conn.recvline().strip()
        conn.close()
        return unhexlify(response)
    except:
        print(f"Error getting cipher for input {hexlify(input_data)}")
        return None

def analyze_position(pos):
    print(f"\nAnalyzing position {pos}")

    # Get ciphertexts with different input patterns
    patterns = {
        'null': b'\x00' * pos,
        'one': b'\x01' * pos,
        'ff': b'\xff' * pos
    }

    results = {}
    for name, pattern in patterns.items():
        cipher = get_cipher(pattern)
        if cipher:
            results[name] = cipher[:32]  # Only store first 32 bytes
            print(f"{name} ({len(pattern)} bytes): {hexlify(results[name]).decode()}")

    # XOR analysis if we have all results
    if len(results) == 3:
        print("\nXOR Relationships:")
        xor_null_one = bytes([a ^ b for a, b in zip(results['null'], results['one'])])
        xor_null_ff = bytes([a ^ b for a, b in zip(results['null'], results['ff'])])
        xor_one_ff = bytes([a ^ b for a, b in zip(results['one'], results['ff'])])

        print(f"null^one: {hexlify(xor_null_one).decode()}")
        print(f"null^ff:  {hexlify(xor_null_ff).decode()}")
        print(f"one^ff:   {hexlify(xor_one_ff).decode()}")

    return results

# First get base ciphertexts
print("Getting base ciphertexts...")
base_ciphers = []
for i in range(2):
    cipher = get_cipher()
    if cipher:
        base_ciphers.append(cipher[:32])
        print(f"Base {i}: {hexlify(base_ciphers[-1]).decode()}")

# Perform analysis for lengths 0-16
results = {}
for i in range(17):
    results[i] = analyze_position(i)

